function shake(){var animatedElements;document.querySelectorAll("[data-animation]").forEach((function(element){var animationType=element.dataset.animation,boundingRect=element.getBoundingClientRect();boundingRect.bottom>0&&boundingRect.top<window.innerHeight&&"saiba-mais-animation"===animationType&&(element.classList.add("saiba-mais-animation"),setTimeout((function(){element.classList.remove("saiba-mais-animation")}),2e3))}))}setInterval(shake,5e3);